import { describe, expect, it } from "vitest"
import { deriveJourney, type JourneyFacts } from "./partner-journey"

const base = (over: Partial<JourneyFacts> = {}): JourneyFacts => ({
  displayName: "Test Partner", agreement: "awaiting_acceptance", acknowledged: {},
  features: { academy: false, resources: false, knowledge: false, objections: false, pipeline: false, performance: false, guidance: false, profilePublication: false },
  content: { courses: 0, lessonsCompleted: 0, resources: 0, resourceCategories: [], knowledgeArticles: 0, objectionResponses: 0 },
  opportunities: 0, allocatedProspects: 0, referralCode: null, meetings: { open: 0, byType: {} }, profile: { eligible: false, status: null }, approvedMarkets: ["United Kingdom"], toolkit: {},
  ...over,
})
const tool = (j: ReturnType<typeof deriveJourney>, key: string) => j.tools.find((t) => t.key === key)!

describe("Operation Empower B2.10 partner journey derivation", () => {
  it("counts only the four required steps and starts with the agreement as the next action", () => {
    const j = deriveJourney(base())
    expect(j.total).toBe(4)
    expect(j.completed).toBe(0)
    expect(j.nextAction?.key).toBe("agreement")
  })

  it("reaches 100% while every optional and future capability is still unavailable", () => {
    const j = deriveJourney(base({ agreement: "accepted", acknowledged: { how_you_earn: "2026-11-24T10:00:00Z", commercial_boundaries: "2026-11-24T10:00:00Z", approved_markets: "2026-11-24T10:00:00Z" } }))
    expect(j.percent).toBe(100)
    expect(j.required.every((s) => s.status === "completed")).toBe(true)
    expect(j.upcoming.length).toBeGreaterThan(0)
    expect(tool(j, "academy").status).toBe("in_development")
    // with no prospects, the recommended next action becomes registering one
    expect(j.nextAction?.key).toBe("pipeline")
  })

  it("never claims content is available when nothing is published or the switch is off", () => {
    const off = deriveJourney(base({ content: { courses: 13, lessonsCompleted: 0, resources: 13, resourceCategories: ["Pricing"], knowledgeArticles: 32, objectionResponses: 12 } }))
    for (const key of ["academy", "pricing_documents", "knowledge_base", "objection_handling"]) expect(tool(off, key).status).not.toBe("available")
    const unpublished = deriveJourney(base({ features: { ...base().features, academy: true, resources: true, knowledge: true } }))
    expect(tool(unpublished, "academy").status).toBe("awaiting_setup")
    expect(tool(unpublished, "pricing_documents").status).toBe("awaiting_setup")
    expect(tool(unpublished, "knowledge_base").status).toBe("awaiting_setup")
  })

  it("marks published content available with a working action", () => {
    const j = deriveJourney(base({ features: { ...base().features, academy: true, resources: true, knowledge: true }, content: { courses: 3, lessonsCompleted: 0, resources: 4, resourceCategories: ["Pricing", "Commission", "Brochure"], knowledgeArticles: 5, objectionResponses: 0 } }))
    expect(tool(j, "academy")).toMatchObject({ status: "available", action: { kind: "link", href: "/partner/academy", label: "Start learning" } })
    expect(tool(j, "pricing_documents").status).toBe("available")
    expect(tool(j, "commission_documents").status).toBe("available")
    expect(tool(j, "industry_demonstrations").status).toBe("awaiting_setup")
    const resumed = deriveJourney(base({ features: { ...base().features, academy: true }, content: { ...base().content, courses: 3, lessonsCompleted: 2 } }))
    expect(tool(resumed, "academy")).toMatchObject({ status: "in_progress", action: { label: "Resume learning" } })
  })

  it("shows built-in tools as available rather than planned", () => {
    const j = deriveJourney(base())
    expect(tool(j, "joint_meetings").status).toBe("available")
    expect(tool(j, "technical_assistance").status).toBe("available")
    expect(tool(j, "founder_training").status).toBe("available")
    expect(tool(j, "referral_identifier")).toMatchObject({ status: "ready_to_set_up", action: { kind: "command", action: "create_referral_code" } })
    expect(tool(deriveJourney(base({ referralCode: "SS-ABCDEFGH" })), "referral_identifier")).toMatchObject({ status: "available", detail: "Your code: SS-ABCDEFGH" })
  })

  it("maps founder fulfilment records for manual items without inventing availability", () => {
    expect(tool(deriveJourney(base()), "email")).toMatchObject({ status: "ready_to_set_up", action: { action: "request_toolkit_item", itemKey: "email" } })
    expect(tool(deriveJourney(base({ toolkit: { email: { status: "awaiting_approval", detail: "please" } } })), "email")).toMatchObject({ status: "awaiting_setup", responsible: "ScaleSmiths founders", action: null })
    expect(tool(deriveJourney(base({ toolkit: { email: { status: "in_preparation", detail: null } } })), "email").status).toBe("in_progress")
    expect(tool(deriveJourney(base({ toolkit: { circlecard: { status: "completed", detail: "Card issued" } } })), "circlecard").status).toBe("completed")
  })

  it("keeps the personal page locked until the five-client milestone", () => {
    expect(tool(deriveJourney(base()), "personal_webpage")).toMatchObject({ status: "coming_soon", action: null })
    expect(tool(deriveJourney(base({ profile: { eligible: true, status: null } })), "personal_webpage").status).toBe("ready_to_set_up")
    expect(tool(deriveJourney(base({ profile: { eligible: true, status: "submitted" } })), "personal_webpage").status).toBe("in_progress")
  })

  it("does not promise researched prospects", () => {
    expect(tool(deriveJourney(base()), "researched_prospects")).toMatchObject({ status: "awaiting_setup" })
    expect(tool(deriveJourney(base()), "researched_prospects").detail).toMatch(/No number is guaranteed/)
    expect(tool(deriveJourney(base({ allocatedProspects: 2 })), "researched_prospects").status).toBe("available")
  })

  it("states when no market is approved instead of implying one", () => {
    expect(deriveJourney(base({ approvedMarkets: [] })).required.find((s) => s.key === "approved_markets")!.detail).toMatch(/has not yet approved a market/)
  })

  it("never shows release dates or percentages for upcoming capabilities", () => {
    for (const u of deriveJourney(base()).upcoming) expect(`${u.title} ${u.benefit}`).not.toMatch(/\d{4}|%|Q[1-4]/)
  })
})

import { readFileSync } from "node:fs"
import { PGlite } from "@electric-sql/pglite"
import { PgDialect } from "drizzle-orm/pg-core"
import type { SQL } from "drizzle-orm"
import { afterAll, beforeAll, beforeEach, describe, expect, it, vi } from "vitest"

const FOUNDER = "10000000-0000-4000-8000-000000000001", USER_A = "10000000-0000-4000-8000-000000000002", USER_B = "10000000-0000-4000-8000-000000000003"
const PARTNER_A = "20000000-0000-4000-8000-000000000001", PARTNER_B = "20000000-0000-4000-8000-000000000002"
const state = vi.hoisted(() => ({ database: null as import("@electric-sql/pglite").PGlite | null, actor: { id: "", role: "independent_partner", sessionVersion: 1, active: true, displayName: "A" } }))
vi.mock("server-only", () => ({}))
vi.mock("@/lib/db", () => ({ db: { transaction: async (op: (tx: { execute: (q: SQL) => Promise<unknown> }) => Promise<unknown>) => state.database!.transaction(async tx => op({ execute: async s => { const q = new PgDialect().sqlToQuery(s); return tx.query(q.sql, q.params) } })) } }))
vi.mock("./rbac", () => ({ requireCapability: async (c: string) => {
  if (c === "expansion.partner" && state.actor.role !== "independent_partner") throw new Error("Forbidden capability")
  if (c === "expansion.manage" && state.actor.role !== "owner") throw new Error("Forbidden capability")
  return { ...state.actor }
} }))
vi.mock("./partner-agreements", () => ({ partnerAgreementOverview: async () => ({ state: "accepted" }) }))
vi.mock("./expansion-profiles", () => ({ getPartnerProfile: async () => ({ eligible: false, versions: [], publication: null }) }))
import { acknowledgeOnboardingStep, getOnboardingAdmin, getPartnerJourney, requestToolkitItem } from "./partner-journey"

const q = <T extends object = Record<string, unknown>>(text: string, params: unknown[] = []) => state.database!.query<T>(text, params)
const as = (id: string, role = "independent_partner") => { state.actor = { id, role, sessionVersion: 1, active: true, displayName: id === USER_A ? "Alex" : "Blake" } }

describe("Operation Empower B2.10 partner journey (PGlite)", () => {
  beforeAll(async () => {
    state.database = new PGlite()
    await state.database.exec(`
      create table admin_users(id uuid primary key,role text,active boolean,session_version integer,display_name text);
      create table expansion_partners(id uuid primary key,user_id uuid references admin_users(id),activated_at timestamptz,agreement_acceptance_id uuid);
      create table expansion_resources(id uuid primary key,status text,audience text,title text);
      create table expansion_toolkit_items(id uuid primary key,partner_id uuid not null references expansion_partners(id),item_key text not null,status text not null check (status in ('not_requested','planned','awaiting_approval','in_preparation','available','completed','unavailable')),detail text,resource_id uuid,completed_at timestamptz,updated_by uuid not null references admin_users(id),updated_at timestamptz not null default now(),unique(partner_id,item_key),check (status not in ('available','completed') or (detail is not null and length(trim(detail))>0)));
      create table expansion_referral_codes(partner_id uuid primary key,code text);
      create table expansion_meeting_requests(id uuid primary key,partner_id uuid,meeting_type text,status text);
      create table expansion_research_candidates(id uuid primary key,status text,allocated_partner_id uuid);
      create table expansion_opportunities(id uuid primary key,partner_id uuid);
      create table expansion_markets(country_code text primary key,country_name text,status text);
      create table empower_content_items(id uuid primary key,kind text,audience text,slug text);
      create table empower_content_versions(id uuid primary key,item_id uuid,status text,review_by date,fields jsonb);
      create table empower_academy_completions(id uuid primary key,partner_id uuid,lesson_version_id uuid);
      create table expansion_audit(id serial primary key,actor_id uuid,entity_id text,action text,details jsonb,created_at timestamptz default now());
    `)
    await state.database.exec(readFileSync(new URL("../../../drizzle/0105_partner_onboarding_progress.sql", import.meta.url), "utf8"))
  }, 30000)
  afterAll(async () => { await state.database?.close() })
  beforeEach(async () => {
    vi.stubEnv("PARTNER_ACADEMY_ENABLED", "true")
    await q("truncate expansion_onboarding_progress,expansion_toolkit_items,expansion_audit,empower_academy_completions,empower_content_versions,empower_content_items,expansion_markets,expansion_partners,admin_users cascade")
    await q("insert into admin_users values($1,'owner',true,1,'Founder'),($2,'independent_partner',true,1,'Alex'),($3,'independent_partner',true,1,'Blake')", [FOUNDER, USER_A, USER_B])
    await q("insert into expansion_partners values($1,$2,now(),null),($3,$4,now(),null)", [PARTNER_A, USER_A, PARTNER_B, USER_B])
    await q("insert into expansion_markets values('GB','United Kingdom','approved'),('US','United States','under_review')")
  })

