// Captures the B2.10 journey previews at the acceptance widths and reports horizontal overflow and small tap targets.
import { createRequire } from "node:module"
const require = createRequire("D:/tmp/ss-b210/admin/package.json")
const { chromium } = require("@playwright/test")
const out = "D:/tmp/ss-b210/docs/expansion/empower/evidence/b2-10"
const widths = [320, 390, 768, 1024, 1440, 1920]
const pages = ["journey", "overview-new-partner", "journey-complete"]
const browser = await chromium.launch({ channel: "chrome" })
const report = []
for (const name of pages) for (const w of widths) {
  const page = await browser.newPage({ viewport: { width: w, height: 900 } })
  await page.goto(`http://127.0.0.1:4710/${name}.html`)
  const r = await page.evaluate(() => {
    const vw = document.documentElement.clientWidth
    const over = [...document.querySelectorAll(".ex-main *")].filter((el) => el.getBoundingClientRect().right > vw + 1 && !el.closest(".ex-table-wrap")).map((el) => el.tagName + "." + String(el.className).slice(0, 30))
    const small = [...document.querySelectorAll(".ex-main button,.ex-main a")].filter((el) => { const b = el.getBoundingClientRect(); return b.height > 0 && b.height < 40 && !el.classList.contains("ex-link") }).map((el) => el.textContent.trim().slice(0, 30))
    return { docScroll: document.documentElement.scrollWidth, vw, over: over.slice(0, 5), small: small.slice(0, 5) }
  })
  await page.screenshot({ path: `${out}/${name}-${w}.png`, fullPage: true })
  report.push({ name, w, ...r })
  await page.close()
}
await browser.close()
console.log(JSON.stringify(report, null, 1))

